begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/costing.inc
set local role authenticated;
select is(pg_temp.cost_intake('c5000000-0000-4000-8000-000000000101',100,'1000','OPENING')#>>'{data,status}','SAVED','explicit cost-bearing opening is atomic');
select is((select status from public.stock_cost_basis_events where stock_item_id='c5000000-0000-4000-8000-000000000101' order by version desc limit 1),'KNOWN','opening basis known');
select is(pg_temp.move('ADJUSTMENT_OUT','c5000000-0000-4000-8000-000000000101',20)#>>'{data,status}','SAVED','actual outflow posts');
select is((select total_cost_minor from public.direct_cost_facts where stock_item_id='c5000000-0000-4000-8000-000000000101'),200::bigint,'exact 20 grams at 10 minor units');
select is(pg_temp.cost_intake('c5000000-0000-4000-8000-000000000101',100,'2000')#>>'{data,status}','SAVED','second cost-bearing receipt posts');
select is((select total_cost_minor from public.direct_cost_facts where stock_item_id='c5000000-0000-4000-8000-000000000101' order by created_at,id limit 1),200::bigint,'later receipt never reprices old usage');
select is(pg_temp.move('ADJUSTMENT_OUT','c5000000-0000-4000-8000-000000000101',9)#>>'{data,status}','SAVED','weighted usage posts');
select is((select total_cost_minor from public.direct_cost_facts where stock_item_id='c5000000-0000-4000-8000-000000000101' and quantity='9.00'),140::bigint,'(800+2000)/180 times 9 is exact 140');
select is(pg_temp.move('OPENING','c5000000-0000-4000-8000-000000000102',100)#>>'{data,status}','SAVED','unpriced opening remains allowed');
select is(pg_temp.move('ADJUSTMENT_OUT','c5000000-0000-4000-8000-000000000102',10)#>>'{data,status}','SAVED','unpriced usage exists');
select is((select status from public.direct_cost_facts where stock_item_id='c5000000-0000-4000-8000-000000000102'),'UNKNOWN','missing cost UNKNOWN');
select is((select total_cost_minor from public.direct_cost_facts where stock_item_id='c5000000-0000-4000-8000-000000000102'),null::bigint,'missing cost is NULL, never zero');
select is(pg_temp.cost_intake('c5000000-0000-4000-8000-000000000102',10,'200')#>>'{data,status}','SAVED','later receipt does not cost unpriced opening');
select is((select status from public.stock_cost_basis_events where stock_item_id='c5000000-0000-4000-8000-000000000102' order by version desc limit 1),'UNKNOWN','mixed unpriced inventory stays conservatively unknown');
select is(pg_temp.cost_basis('c5000000-0000-4000-8000-000000000102','0',3)#>>'{data,status}','SAVED','explicit future zero unit cost accepted');
select is(pg_temp.move('ADJUSTMENT_OUT','c5000000-0000-4000-8000-000000000102',1)#>>'{data,status}','SAVED','new usage after reviewed zero');
select is((select total_cost_minor from public.direct_cost_facts where stock_item_id='c5000000-0000-4000-8000-000000000102' and quantity='1.00'),0::bigint,'measured zero cost distinct');
select is((select status from public.direct_cost_facts where stock_item_id='c5000000-0000-4000-8000-000000000102' and quantity='10.00'),'UNKNOWN','future correction does not heal historical unknown');
select throws_ok($$update public.direct_cost_facts set total_cost_minor=0$$,'42501',null,'normal authenticated cannot update cost');
select throws_ok($$delete from public.direct_cost_facts$$,'42501',null,'normal authenticated cannot delete cost');
select throws_ok($$insert into public.direct_cost_facts(id) values(gen_random_uuid())$$,'42501',null,'direct insertion forbidden');
select is(pg_temp.cost_basis('c5000000-0000-4000-8000-000000000102','1',3)->>'code','COST_CONFLICT','conditional basis version blocks stale correction');
reset role;
select ok((select count(*)>0 from public.audit_events where action='costing.direct_cost_created'),'direct costs audited');
select throws_ok($$update public.stock_cost_basis_events set value_numerator=0$$,'23514',null,'immutable cost basis even under privileged accidental writes');
select is(app_private.cost_round(1,2),1::bigint,'half-up allocation positive');
select is(app_private.cost_round(-1,2),(-1)::bigint,'symmetric compensating rounding');
select is(app_private.cost_round(9999999999999999::numeric*3333,10000),3333000000000000::bigint,'large exact arithmetic avoids binary float');
select * from finish();rollback;
